package com.hbm.client.forcefield;
import com.hbm.client.model.*;import com.hbm.machine.forcefield.*;import com.mojang.blaze3d.vertex.PoseStack;import com.mojang.math.Axis;import net.minecraft.client.Minecraft;import net.minecraft.client.renderer.*;import net.minecraft.client.renderer.blockentity.*;import net.minecraft.resources.ResourceLocation;import net.minecraft.world.phys.AABB;
/** Source base yaw180 and top atY1; active top rotation is wallclock/10, independent of sphere tessellation. */
public final class ForceFieldRenderer implements BlockEntityRenderer<ForceFieldBlockEntity> {
 static final ResourceLocation BODY=ForceFieldContent.id("models/radar_base.obj"),TOP=ForceFieldContent.id("models/forcefield_top.obj"),BODY_TEXTURE=ForceFieldContent.id("textures/models/forcefield_base.png"),TOP_TEXTURE=ForceFieldContent.id("textures/models/forcefield_top.png");
 public ForceFieldRenderer(BlockEntityRendererProvider.Context context){}
 private static void body(PoseStack poses,MultiBufferSource buffers,int light,int overlay,boolean world){var mesh=LegacyObjModels.INSTANCE.get(Minecraft.getInstance().getResourceManager(),BODY);LegacyObjRenderer.renderAll(mesh,poses,buffers.getBuffer(world?RenderType.entityCutoutNoCull(BODY_TEXTURE):RenderType.entityCutout(BODY_TEXTURE)),light,overlay,0xffffffff,LegacyObjRenderer.Convention.HFR_FLAT);}
 private static void top(PoseStack poses,MultiBufferSource buffers,int light,int overlay,boolean world){var mesh=LegacyObjModels.INSTANCE.get(Minecraft.getInstance().getResourceManager(),TOP);LegacyObjRenderer.renderAll(mesh,poses,buffers.getBuffer(world?RenderType.entityCutoutNoCull(TOP_TEXTURE):RenderType.entityCutout(TOP_TEXTURE)),light,overlay,0xffffffff,LegacyObjRenderer.Convention.FORGE);}
 static void inventory(PoseStack poses,MultiBufferSource buffers,int light,int overlay){body(poses,buffers,light,overlay,false);poses.translate(0,1,0);top(poses,buffers,light,overlay,false);}
 /** Original unregistered TileEntityFF/RenderForceField presentation, retained without inventing a host registry. */
 public static void prototype(PoseStack poses,MultiBufferSource buffers,int light,int overlay){poses.pushPose();poses.translate(.5,0,.5);poses.mulPose(Axis.YP.rotationDegrees(180));var mesh=LegacyObjModels.INSTANCE.get(Minecraft.getInstance().getResourceManager(),BODY);LegacyObjRenderer.renderAll(mesh,poses,buffers.getBuffer(RenderType.entityCutoutNoCull(ForceFieldContent.id("textures/models/radar_base.png"))),light,overlay,0xffffffff,LegacyObjRenderer.Convention.HFR_FLAT);poses.translate(0,.5,0);ForceFieldWireframe.prototype(poses,buffers);poses.popPose();}
 @Override public void render(ForceFieldBlockEntity field,float partial,PoseStack poses,MultiBufferSource buffers,int light,int overlay){var mesh=LegacyObjModels.INSTANCE.get(Minecraft.getInstance().getResourceManager(),BODY);LegacyContactShadows.render(field,mesh,new org.joml.Matrix4f().translation(.5F,0,.5F).rotateY((float)Math.PI),poses,buffers);poses.pushPose();poses.translate(.5,0,.5);poses.mulPose(Axis.YP.rotationDegrees(180));body(poses,buffers,light,overlay,true);poses.translate(0,.5,0);if(field.fieldVisible()){int segments=(int)(16+field.radius*.125);ForceFieldWireframe.render(poses,buffers,segments,segments*2,field.radius,field.color);double rotation=System.currentTimeMillis()/10D%360;poses.mulPose(Axis.YP.rotationDegrees((float)-rotation));}poses.translate(0,.5,0);top(poses,buffers,light,overlay,true);poses.popPose();}
 @Override public boolean shouldRenderOffScreen(ForceFieldBlockEntity field){return true;}
 @Override public int getViewDistance(){return Math.max(256,(int)Math.ceil(ForceFieldConfig.baseRadius+16D*ForceFieldConfig.radUpgrade+256));}
 @Override public AABB getRenderBoundingBox(ForceFieldBlockEntity field){var pos=field.getBlockPos();double radius=Math.max(1.5,field.radius);return new AABB(pos.getX()+.5-radius,pos.getY()+.5-radius,pos.getZ()+.5-radius,pos.getX()+.5+radius,pos.getY()+.5+radius,pos.getZ()+.5+radius);}
}
